<template>
  <div class="optional-seed-section">
    <div class="seed-section">
      <div 
        class="seed-header"
        @click="toggleOptions"
      >
        <span class="seed-title">{{ title }} ({{ t('optional') }})</span>
        <l-img 
          w="18px" 
          h="18px" 
          src="/static/images/up-icon.png" 
          :class="{'rotate': isExpanded}" 
          class="seed-arrow"
        />
      </div>
      
      <transition name="expand">
        <div v-show="isExpanded" class="seed-content">
          <p class="seed-description">{{ description }}</p>
          <el-input
            v-model.number="inputValue"
            type="number"
            :placeholder="placeholder"
            class="seed-input"
            :min="min"
            :max="max"
            @input="updateValue"
          />
        </div>
      </transition>
    </div>
  </div>
</template>

<script setup>
import { ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import LImg from '@/components/l-img.vue';

const { t } = useI18n();

// 定义props
const props = defineProps({
  modelValue: {
    type: [Number, String],
    default: ''
  },
  title: {
    type: String,
    default: 'Seed'
  },
  description: {
    type: String,
    default: ''
  },
  placeholder: {
    type: String,
    default: ''
  },
  min: {
    type: Number,
    default: Number.MIN_SAFE_INTEGER
  },
  max: {
    type: Number,
    default: Number.MAX_SAFE_INTEGER
  }
});

// 定义事件
const emit = defineEmits(['update:modelValue', 'expand-change']);

// 内部状态
const isExpanded = ref(false);
const inputValue = ref(props.modelValue);

// 监听外部值变化
watch(() => props.modelValue, (newVal) => {
  inputValue.value = newVal;
});

// 更新值
const updateValue = () => {
  emit('update:modelValue', inputValue.value);
};

// 切换展开/收起
const toggleOptions = () => {
  isExpanded.value = !isExpanded.value;
  emit('expand-change', isExpanded.value);
};
</script>

