<template>
  <div class="ai-media-ratio-selector">
    <!-- 比例选项网格 -->
    <div class="ratio-grid" :class="{ 'expanded': isExpanded }">
      <div
        v-for="ratio in displayedOptions"
        :key="ratio.value"
        class="ratio-item"
        :class="{ 'active': modelValue === ratio.value }"
        @click="handleSelect(ratio.value)"
      >
        <div class="ratio-preview" :style="getRatioStyle(ratio)"></div>
        <span class="ratio-label">{{ ratio.label }}</span>
      </div>
      
    </div>
    <div 
        class="more-options-button"
        @click="toggleExpanded"
      >
      <l-img w="18px" h="18px" src="/static/images/up-icon.png" :class="{'rotate': isExpanded}" class="expand-icon"></l-img>
      <span class="more-text">{{ t('moreOptions') }}</span>
      </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue';
import { useI18n } from 'vue-i18n';
import LImg from '@/components/l-img.vue';
import { videoDefaultRatioOptions, videoAllRatioOptions, imageDefaultRatioOptions, imageAllRatioOptions } from '@/types/panel-options';
import { pxToRem } from '@/utils/px-to-rem';

const { t } = useI18n();

const props = defineProps({
  modelValue: {
    type: String,
    default: ''
  },
  type: {
    type: String,
    default: 'video'
  }
});

const emit = defineEmits(['update:modelValue']);

const isExpanded = ref(false);

// 计算显示的选项
const displayedOptions = computed(() => {
  if(props.type === 'video'){
    return isExpanded.value ? videoAllRatioOptions : videoDefaultRatioOptions;
  }else{
    return isExpanded.value ? imageAllRatioOptions : imageDefaultRatioOptions;
  }
});


// 方法
const handleSelect = (value) => {
  emit('update:modelValue', value);
};

const toggleExpanded = () => {
  isExpanded.value = !isExpanded.value;
};

const getRatioStyle = (ratio) => {
  const containerSize = 29; // 容器尺寸
  const aspectRatio = ratio.width / ratio.height;
  
  let width, height;
  if (aspectRatio >= 1) {
    // 宽度较大的比例
    width = containerSize;
    height = containerSize / aspectRatio;
  } else {
    // 高度较大的比例
    height = containerSize;
    width = containerSize * aspectRatio;
  }
  
  return {
    width: pxToRem(`${Math.max(width, 8)}px`),
    height: pxToRem(`${Math.max(height, 8)}px`)
  };
};
</script>

